    ('Connect your Facebook Page (Settings → API Connection) and an Order on Messenger button will show on your store by itself.', 'আপনার Facebook Page সংযোগ করুন (সেটিংস → API সংযোগ) — তাহলেই আপনার দোকানে নিজে নিজে Order on Messenger বোতাম দেখা যাবে।'),
